```java
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.SessionAttributes;

@Controller
@SessionAttributes("user")
public class UserProfileController {

    // 模拟数据库中的用户对象
    private static class User {
        private String username;
        private String email;
        private boolean admin;
        private String role;

        public String getUsername() { return username; }
        public void setUsername(String username) { this.username = username; }
        public String getEmail() { return email; }
        public void setEmail(String email) { this.email = email; }
        public boolean isAdmin() { return admin; }
        public void setAdmin(boolean admin) { this.admin = admin; }
        public String getRole() { return role; }
        public void setRole(String role) { this.role = role; }
    }

    @GetMapping("/profile")
    public String showProfile(@ModelAttribute("user") User user) {
        return "profile";
    }

    @PostMapping("/profile/update")
    public String updateProfile(@ModelAttribute User user, Model model) {
        // 仅允许用户更新自己的基本资料，不包含 admin 和 role 字段
        User existing = getCurrentUserFromDB(user.getUsername());
        existing.setEmail(user.getEmail());
        // 注意：这里只显式复制了 email，但 Spring 的 @ModelAttribute 已经将
        // HTTP 参数直接绑定到 user 对象上，包括 admin 和 role 字段。
        saveToDB(existing);
        model.addAttribute("user", existing);
        return "redirect:/profile";
    }

    private User getCurrentUserFromDB(String username) {
        User u = new User();
        u.setUsername(username);
        u.setEmail("existing@example.com");
        u.setAdmin(false);
        u.setRole("USER");
        return u;
    }

    private void saveToDB(User user) {
        // 模拟持久化
        System.out.println("Saving user: " + user.getUsername() +
                           ", admin=" + user.isAdmin() +
                           ", role=" + user.getRole());
    }
}

```
